@theme {
  --color-paper: #f4efe4;
  --color-paper-deep: #e8e0d0;
  --color-ink: #1a1f2e;
  --color-ink-soft: #3d4558;
  --color-muted: #6b7280;
  --color-line: #d4cbb8;
  --color-surface: #faf7f0;
  --color-surface-2: #ffffff;
  --color-accent: #0f6b5c;
  --color-accent-soft: #d8ebe6;
  --color-accent-ink: #0a4a40;
  --color-warn: #9a5b1a;
  --color-warn-soft: #f5e6d0;
  --color-danger: #8b2e2e;
  --color-danger-soft: #f3dede;
  --color-silver: #8a9199;
  --color-domain-1: #0f6b5c;
  --color-domain-2: #1e4d7b;
  --color-domain-3: #6b4c9a;
  --color-domain-4: #9a5b1a;
  --color-domain-5: #8b2e4a;
  --font-display: "Fraunces", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --font-sans: "Source Sans 3", "Source Sans Pro", system-ui, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  --radius-sm: 0.375rem;
  --radius: 0.625rem;
  --radius-lg: 1rem;
  --shadow-card: 0 1px 0 rgba(26, 31, 46, 0.04), 0 8px 24px rgba(26, 31, 46, 0.06);
}

@layer base {
  html {
    font-family: var(--font-sans);
    color: var(--color-ink);
    background: var(--color-paper);
    -webkit-font-smoothing: antialiased;
  }
  body {
    margin: 0;
    min-height: 100dvh;
    background:
      radial-gradient(1200px 600px at 10% -10%, rgba(15, 107, 92, 0.07), transparent 55%),
      radial-gradient(900px 500px at 100% 0%, rgba(154, 91, 26, 0.05), transparent 50%),
      var(--color-paper);
  }
  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }
  :focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }
  ::selection {
    background: var(--color-accent-soft);
    color: var(--color-accent-ink);
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

