export function WeightRing({ activeId }: { activeId?: string }) {
  const modules = course.modules;
  const r = 54;
  const c = 2 * Math.PI * r;
  let offset = 0;
  const segments = modules.map((m) => {
    const len = (m.weight_pct / 100) * c;
    const seg = { ...m, len, offset };
    offset += len;
    return seg;
  });

  return (
    <div className="flex flex-col items-center gap-4 sm:flex-row sm:items-center sm:gap-8">
      <svg viewBox="0 0 140 140" className="h-40 w-40 shrink-0" aria-hidden>
        <circle cx="70" cy="70" r={r} fill="none" stroke="var(--color-paper-deep)" strokeWidth="16" />
        {segments.map((s) => (
          <circle
            key={s.id}
            cx="70"
            cy="70"
            r={r}
            fill="none"
            stroke={colors[s.id]}
            strokeWidth={activeId === s.id ? 20 : 16}
            strokeDasharray={`${s.len} ${c - s.len}`}
            strokeDashoffset={-s.offset}
            strokeLinecap="butt"
            transform="rotate(-90 70 70)"
            opacity={activeId && activeId !== s.id ? 0.35 : 1}
          />
        ))}
        <text
          x="70"
          y="66"
          textAnchor="middle"
          className="fill-[var(--color-ink)]"
          style={{ fontSize: "11px", fontFamily: "var(--font-mono)" }}
        >
          60 items
        </text>
        <text
          x="70"
          y="82"
          textAnchor="middle"
          className="fill-[var(--color-muted)]"
          style={{ fontSize: "10px", fontFamily: "var(--font-mono)" }}
        >
          120 min
        </text>
      </svg>
      <ul className="grid w-full gap-2 text-sm">
        {modules.map((m) => (
          <li key={m.id} className="flex items-center gap-2">
            <span
              className="h-2.5 w-2.5 shrink-0 rounded-full"
              style={{ background: colors[m.id] }}
            />
            <span className="font-mono text-xs text-[var(--color-muted)]">{m.id}</span>
            <span className="min-w-0 flex-1 truncate text-[var(--color-ink-soft)]">
              {m.name}
            </span>
            <span className="font-mono text-xs font-semibold text-[var(--color-ink)]">
              {m.weight_pct}%
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useState } from "react";
import { cn } from "@/lib/utils";

export function SequentialPulse({
  steps,
  accent = "var(--color-accent)",
  intervalMs = 1600,
}: {
  steps: string[];
  accent?: string;
  intervalMs?: number;
}) {
  const [i, setI] = useState(0);
  useEffect(() => {
    const reduced =
      typeof window !== "undefined" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) return;
    const t = setInterval(() => setI((x) => (x + 1) % steps.length), intervalMs);
    return () => clearInterval(t);
  }, [steps.length, intervalMs]);

  return (
    <div
      className="rounded-[var(--radius-lg)] border border-[var(--color-line)] bg-[var(--color-surface-2)] p-4 shadow-[var(--shadow-card)]"
      role="list"
      aria-label="Sequential steps"
    >
      <div className="mb-3 flex items-center justify-between gap-2">
        <p className="text-xs font-semibold uppercase tracking-[0.14em] text-[var(--color-muted)]">
          Sequential pulse
        </p>
        <p className="font-mono text-xs text-[var(--color-muted)]">
          {i + 1}/{steps.length}
        </p>
      </div>
      <ol className="space-y-2">
        {steps.map((step, idx) => {
          const active = idx === i;
          return (
            <li key={step}>
              <button
                type="button"
                onClick={() => setI(idx)}
                className={cn(
                  "flex w-full items-start gap-3 rounded-[var(--radius)] border px-3 py-2.5 text-left transition-colors",
                  active
                    ? "border-transparent text-[var(--color-ink)]"
                    : "border-transparent text-[var(--color-ink-soft)] opacity-70 hover:opacity-100",
                )}
                style={
                  active
                    ? {
                        background: "color-mix(in srgb, " + accent + " 12%, white)",
                        boxShadow: "inset 3px 0 0 " + accent,
                      }
                    : undefined
                }
                role="listitem"
                aria-current={active ? "step" : undefined}
              >
                <span
                  className="mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-full font-mono text-xs font-semibold"
                  style={{
                    background: active ? accent : "var(--color-paper-deep)",
                    color: active ? "white" : "var(--color-muted)",
                  }}
                >
                  {idx + 1}
                </span>
                <span className="text-sm leading-snug md:text-[0.95rem]">{step}</span>
              </button>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

